.card:before{content:'';position:absolute;inset:7px;border:1px solid #ffffff0b;pointer-events:none}.eyebrow{font:10px 'DM Mono',monospace;letter-spacing:.24em;color:var(--gold);text-transform:uppercase}.card h1{font-size:clamp(36px,8vw,60px);line-height:.98;letter-spacing:-.07em;margin:15px 0 12px;font-weight:800}.card h1 em{font-style:normal;color:var(--gold)}.card p{max-width:370px;margin:0 auto 23px;color:#c5c1c4;font-size:13px;line-height:1.75}.rules{display:flex;justify-content:center;gap:18px;margin:0 auto 26px;color:#aaa6ae;font:9px 'DM Mono',monospace;letter-spacing:.07em}.rules b{color:#f2e7d5}.primary{border:0;background:linear-gradient(105deg,#ffcf82,#f4a85f);color:#251b19;padding:14px 28px;font:800 11px Manrope,sans-serif;letter-spacing:.16em;text-transform:uppercase;cursor:pointer;min-width:190px;box-shadow:0 8px 28px #ffb85b30}.primary:active{transform:translateY(1px)}.power-toast{position:absolute;z-index:4;left:50%;top:38%;transform:translate(-50%,-50%) scale(.94);opacity:0;text-align:center;pointer-events:none;transition:.5s}.power-toast.show{opacity:1;transform:translate(-50%,-50%) scale(1)}.power-toast .eyebrow{color:#ffe0a2}.power-toast strong{display:block;font-size:24px;letter-spacing:-.04em;margin-top:5px;text-shadow:0 4px 20px #000}.mobile-tip{display:none}
@media (max-width:650px){.topbar{left:15px;right:15px}.brand-name{font-size:10px}.sigil{width:31px;height:31px}.health-box{width:clamp(122px,37vw,170px)}.hud{gap:0}.boss-box{top:82px;width:62vw}.stage-label{top:139px;left:15px;font-size:8px}.hint{display:none}.controls{bottom:max(17px,env(safe-area-inset-bottom));left:15px;right:15px}.move-pad,.action-pad{gap:8px}.rules{gap:9px;font-size:8px}.mobile-tip{display:block;color:#a49fac;font:9px 'DM Mono',monospace;margin-top:15px}}
@media (orientation:landscape) and (max-height:520px){.topbar{top:10px}.boss-box{top:65px}.stage-label{top:118px}.control{width:52px;height:52px}.control.attack{width:62px;height:62px}.controls{bottom:10px}.skill-caption{bottom:78px}.card{padding:22px}.card h1{font-size:40px;margin:8px}.card p{margin-bottom:13px}}

